"""Worker pool used by the report rollups."""
import threading


class Pool:
    def __init__(self):
        # A single lock guards both the queue and the reports. Using one
        # lock removes the handoff/claim deadlock: handoff used to take
        # _report_lock -> _queue_lock while claim took _queue_lock ->
        # _report_lock, and a concurrent pair of calls could deadlock.
        self._lock = threading.Lock()
        self._queue = []
        self._reports = {}

    def submit(self, job):
        with self._lock:
            self._queue.append(job)

    def handoff(self, worker_id, report):
        # Record the report before claiming the next job, so a worker never
        # holds two jobs at once.
        with self._lock:
            self._reports[worker_id] = report
            if self._queue:
                return self._queue.pop(0)
        return None

    def claim(self, worker_id):
        with self._lock:
            self._reports.setdefault(worker_id, None)
            if self._queue:
                return self._queue.pop(0)
        return None

