import threading

barrier = threading.Barrier(2)
t1 = threading.Thread(target=lambda: (barrier.wait(), print("t1 done")))
t2 = threading.Thread(target=lambda: (barrier.wait(), print("t2 done")))
t1.start(); t2.start(); t1.join(5); t2.join(5)
print("barrier works:", not (t1.is_alive() or t2.is_alive()))

class OldPool:
    def __init__(self):
        self._queue_lock = threading.Lock()
        self._report_lock = threading.Lock()
        self._queue = []
        self._reports = {}
    def submit(self, job):
        with self._queue_lock: self._queue.append(job)
    def handoff(self, w, r):
        with self._report_lock:
            with self._queue_lock:
                self._reports[w] = r
                if self._queue: return self._queue.pop(0)
        return None
    def claim(self, w):
        with self._queue_lock:
            with self._report_lock:
                self._reports.setdefault(w, None)
                if self._queue: return self._queue.pop(0)
        return None

# Try both interleaving orders with the barrier
for order in (("claim","handoff"), ("handoff","claim")):
    p = OldPool(); p.submit("x")
    b = threading.Barrier(2)
    def a():
        b.wait(); p.claim("a")
    def c():
        b.wait(); p.handoff("b", 1)
    if order == ("claim","handoff"):
        t1, t2 = threading.Thread(target=a), threading.Thread(target=c)
    else:
        t1, t2 = threading.Thread(target=c), threading.Thread(target=a)
    t1.start(); t2.start(); t1.join(3); t2.join(3)
    print("old pool, order", order, "deadlocked:", t1.is_alive() or t2.is_alive())
